-- ------------------------------------------------------------------ registrants (year 3+)
INSERT INTO registrations (id, event_id, user_id, dept, status, checked_in, checked_in_at, attend_via, registered_at)
SELECT 105600 + ROW_NUMBER() OVER (ORDER BY u.id), 1056, u.id, u.dept,
       IF(u.id = 1023, 'absent', 'attended'),
       IF(u.id = 1023, 0, 1),
       IF(u.id = 1023, NULL, TIMESTAMP('2026-08-27', SEC_TO_TIME(12 * 3600 + 40 * 60 + (u.id % 19) * 60))),
       'onsite',
       TIMESTAMP('2026-08-13' + INTERVAL (u.id % 13) DAY, '12:10:00')
FROM users u
WHERE u.role = 'student'
  AND CAST(REGEXP_SUBSTR(u.dept, '[0-9]+') AS UNSIGNED) >= 3
  AND NOT EXISTS (SELECT 1 FROM blacklist_entries b WHERE b.user_id = u.id AND b.restored_at IS NULL);

INSERT INTO registration_checkins (registration_id, event_date, checked_in_at)
SELECT r.id, '2026-08-27', r.checked_in_at FROM registrations r WHERE r.event_id = 1056 AND r.checked_in = 1;

